CREATE COLUMN TABLE "TEST_AP"."OCLT" ("Code" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "Active" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCLT_NAME" ON "TEST_AP"."OCLT" ( "Name" ASC )